            @Override
            public WebElement apply(WebDriver input) {
                return parent.findElement(locator);
            }
        });
    }
    private void moveToElementLocatedBy(By by) {
        WebElement webElement = waitUntilPresenceOfElementLocated(by);
        moveToElement(webElement);
