import { Injectable, inject, signal } from '@angular/core';
import { HttpClient } from '@angular/common/http';

export interface Manufacturer { id?: number; name: string; cars?: unknown[]; }
export interface Car { id?: number; model: string; manufacturer?: Manufacturer; [k: string]: unknown; }
export interface Rating { id?: number; rating: number | null; car: Car | null; }
export interface ManufacturerRating { manufacturer: string; rating: number; }
export interface Msg { id: number; text: string; kind: 'success' | 'error'; }

@Injectable({ providedIn: 'root' })
export class ApiService {
  private http = inject(HttpClient);
  manufacturers() { return this.http.get<Manufacturer[]>('/api/manufacturers'); }
  saveManufacturer(m: Manufacturer) { return this.http.post<Manufacturer>('/api/manufacturers', m); }
  deleteManufacturer(id: number) { return this.http.delete<void>(`/api/manufacturers/${id}`); }
  averages() { return this.http.get<ManufacturerRating[]>('/api/manufacturers/ratings'); }
  ratings() { return this.http.get<Rating[]>('/api/ratings'); }
  saveRating(r: Rating) { return this.http.post<Rating>('/api/ratings', r); }
  deleteRating(id: number) { return this.http.delete<void>(`/api/ratings/${id}`); }
  cars() { return this.http.get<Car[]>('/api/cars', { params: { offset: 0, limit: -1 } }); }
}

@Injectable({ providedIn: 'root' })
export class MessageService {
  messages = signal<Msg[]>([]);
  private n = 0;
  show(text: string, kind: 'success' | 'error') {
    const id = ++this.n;
    this.messages.update((m) => [...m, { id, text, kind }]);
    setTimeout(() => this.close(id), 5000);
  }
  success(t: string) { this.show(t, 'success'); }
  error(t: string) { this.show(t, 'error'); }
  close(id: number) { this.messages.update((m) => m.filter((x) => x.id !== id)); }
}
