import { Component, inject, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { ApiService, Manufacturer, MessageService } from './api.service';

@Component({
  selector: 'app-manufacturers',
  standalone: true,
  imports: [FormsModule],
  template: `
    <div class="big-title"><h2>Manufacturers</h2>
      <button id="gwt-debug-create-manufacturer" class="add-action" (click)="create()">Create</button></div>
    <table id="gwt-debug-manufacturers">
      <thead><tr><th>ID</th><th>Name</th><th>Edit</th><th>Delete</th></tr></thead>
      <tbody>
        @for (m of rows(); track m.id) {
          <tr><td>{{ m.id }}</td><td>{{ m.name }}</td>
            <td><button (click)="edit(m)">Edit</button></td>
            <td><button (click)="remove(m)">Delete</button></td></tr>
        }
      </tbody>
    </table>
    @if (editing()) {
      <div class="glass"><div class="popup" id="gwt-debug-manufacturer-editor">
        <div><span>Name:</span> <input id="gwt-debug-manufacturer-input" [(ngModel)]="name"></div>
        <div><button id="gwt-debug-manufacturer-save" (click)="save()">Save</button>
          <button id="gwt-debug-manufacturer-close" (click)="editing.set(null)">Close</button></div>
      </div></div>
    }`,
})
export class ManufacturersComponent {
  private api = inject(ApiService);
  private msg = inject(MessageService);
  rows = signal<Manufacturer[]>([]);
  editing = signal<Manufacturer | null>(null);
  name = '';
  constructor() {
    this.api.manufacturers().subscribe({ next: (r) => this.rows.set(r), error: () => this.msg.error('Failed to load manufacturers') });
  }
  create() { this.name = ''; this.editing.set({ name: '' }); }
  edit(m: Manufacturer) { this.name = m.name; this.editing.set({ ...m }); }
  save() {
    const cur = this.editing();
    if (!cur) return;
    this.api.saveManufacturer({ ...cur, name: this.name }).subscribe({
      next: (s) => {
        this.rows.update((r) => cur.id == null ? [...r, s] : r.map((x) => (x.id === cur.id ? s : x)));
        this.msg.success('Manufacturer saved');
        this.editing.set(null);
      },
      error: () => this.msg.error('Failed to save manufacturer'),
    });
  }
  remove(m: Manufacturer) {
    if (!window.confirm(`Are you sure you want to delete ${m.name}?`)) return;
    this.api.deleteManufacturer(m.id!).subscribe({
      next: () => this.rows.update((r) => r.filter((x) => x.id !== m.id)),
      error: () => this.msg.error('Failed to delete manufacturer'),
    });
  }
}
