        }
      </tbody>
    </table>
    @if (open()) {
      <div class="glass"><div class="popup">
        <div><span>Car:</span>
          <select [(ngModel)]="car">
            @for (c of cars(); track c.id) { <option [ngValue]="c">{{ c.manufacturer?.name }}/{{ c.model }}</option> }
          </select></div>
        <div><span>Your rating:</span>
          <input id="gwt-debug-ratingInput" type="number" maxlength="3" [(ngModel)]="value"></div>
        <div><button id="gwt-debug-ratingSave" (click)="save()">Save</button>
          <button (click)="open.set(false)">Close</button></div>
      </div></div>
    }`,
})
export class RatingsComponent {
  private api = inject(ApiService);
  private msg = inject(MessageService);
  rows = signal<Rating[]>([]);
  cars = signal<Car[]>([]);
  open = signal(false);
  car: Car | null = null;
  value: number | null = null;
  constructor() {
    this.api.ratings().subscribe({ next: (r) => this.rows.set(r), error: () => this.msg.error('Failed to load ratings') });
  }
  label(r: Rating) { return r.car?.manufacturer ? `${r.car.manufacturer.name}/${r.car.model}` : ''; }
  create() {
    this.api.cars().subscribe({
      next: (c) => { this.cars.set(c); this.car = c[0] ?? null; this.value = null; this.open.set(true); },
      error: () => this.msg.error('Failed to load cars'),
    });
  }
  save() {
    this.api.saveRating({ car: this.car, rating: this.value }).subscribe({
      next: (s) => {
        this.rows.update((r) => [...r, s]);
        this.msg.success('Rating saved');
        this.open.set(false);
      },
      error: () => this.msg.error('Failed to save rating'),
    });
  }
  remove(r: Rating) {
    if (!window.confirm(`Are you sure you want to delete ${this.label(r)}?`)) return;
    this.api.deleteRating(r.id!).subscribe({
      next: () => this.rows.update((x) => x.filter((y) => y.id !== r.id)),
      error: () => this.msg.error('Failed to delete rating'),
    });
  }
}
